from itertools import permutations, product


def fmt(t):
    if t < 720:
        period = "AM"
        hour = t // 60
        if hour == 0:
            hour = 12
    else:
        period = "PM"
        hour = (t - 720) // 60
        if hour == 0:
            hour = 12
    return f"{hour}:{t % 60:02d}{period}"


