    },
]

start_loc = "Richmond District"
start_time = 540

best_key = None
best_stmts = None

for r in range(1, len(friends) + 1):
    for perm in permutations(friends, r):
        start_ranges = [
            range(f["start"], f["end"] - f["min"] + 1)
            for f in perm
        ]

        for starts in product(*start_ranges):
            cur_t = start_time
            cur_loc = start_loc
            total_meeting = 0
            ends = []
            feasible = True

            for i, f in enumerate(perm):
                s = starts[i]
                d = travel_time(cur_loc, f["loc"])

                if s < cur_t + d:
                    feasible = False
                    break

                if i < len(perm) - 1:
                    next_f = perm[i + 1]
                    d_next = travel_time(f["loc"], next_f["loc"])
                    e = min(f["end"], starts[i + 1] - d_next)
                else:
                    e = f["end"]

                if e < s + f["min"]:
                    feasible = False
                    break

                total_meeting += e - s
                ends.append((s, e))
                cur_t = e
                cur_loc = f["loc"]

            if feasible:
                finish = ends[-1][1]
                key = (len(perm), total_meeting, -finish)

                if best_key is None or key > best_key:
                    stmts = [
                        f"You start at {start_loc} at {fmt(start_time)}."
                    ]
                    cur_t = start_time
                    cur_loc = start_loc

                    for f, (s, e) in zip(perm, ends):
                        d = travel_time(cur_loc, f["loc"])

                        if d > 0:
                            arrive = cur_t + d
                            stmts.append(
                                f"You travel to {f['loc']} in {d} minutes "
                                f"and arrive at {fmt(arrive)}."
                            )
                            cur_t = arrive

                        if cur_t < s:
                            stmts.append(f"You wait until {fmt(s)}.")
                            cur_t = s

                        stmts.append(
                            f"You meet {f['name']} for {e - s} minutes "
                            f"from {fmt(s)} to {fmt(e)}."
                        )
                        cur_t = e
                        cur_loc = f["loc"]

                    best_key = key
                    best_stmts = stmts

